mapper.select:
SELECT srr.id, srrd.main_id, srrd.sku_id, srrd.sku_no, srrd.return_qty, srrd.receive_qty, srrd.return_type_dict, srrd.return_reason_dict, srrd.remark, srrd.source_detail_id, srr.approce_status FROM so_return_receive_detail srrd INNER JOIN so_return_receive srr ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE WHERE srr.is_deleted = FALSE
and srr.source_id in
#{id}
